CREATE VIEW dbo.IV_Q$GESTAO_PRODUTO___AMS ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , ITENS_AMS, COM_INSTALACAO_AMS, ITENS_A_AGREGAR, ITENS_A_DESAGREGAR, ORDEM_SERVICO_AGREGA, QUANTIDADE_ITENS, CHASSI_AMS___1, CHASSI_AMS___2, CHASSI_AMS___3, CHASSI_AMS___4, CHASSI_AMS___5, CHASSI_AMS___6, CHASSI_AMS___7, CHASSI_AMS___8, CHASSI_AMS___9, CHASSI_AMS___10, COMAR, PRODUTO_NOVO_OU_USAD, FORMULARIO_NUMERO, NUMERO, DESCONTO_INCONDICION, DATA_ESPERADA_PARA_E, DATA_DE_USO_PARA_SAZ, PREVISAO_ENTREGA_PRE, DATA_ENTREGA, TRANSPORTADORA, VALOR_FRETE, TRANSPORTE_ENTREGA)     AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.ITENS_AMS, TABF.COM_INSTALACAO_AMS, TABF.ITENS_A_AGREGAR, TABF.ITENS_A_DESAGREGAR, TABF.ORDEM_SERVICO_AGREGA, TABF.QUANTIDADE_ITENS, TABF.CHASSI_AMS___1, TABF.CHASSI_AMS___2, TABF.CHASSI_AMS___3, TABF.CHASSI_AMS___4, TABF.CHASSI_AMS___5, TABF.CHASSI_AMS___6, TABF.CHASSI_AMS___7, TABF.CHASSI_AMS___8, TABF.CHASSI_AMS___9, TABF.CHASSI_AMS___10, TABF.COMAR, TABF.PRODUTO_NOVO_OU_USAD, TABF.FORMULARIO_NUMERO, TABF.NUMERO, TABF.DESCONTO_INCONDICION, TABF.DATA_ESPERADA_PARA_E, TABF.DATA_DE_USO_PARA_SAZ, TABF.PREVISAO_ENTREGA_PRE, TABF.DATA_ENTREGA, TABF.TRANSPORTADORA, TABF.VALOR_FRETE, TABF.TRANSPORTE_ENTREGA    FROM IV_Q_GESTAO_PRODUTO___AMS TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA 